using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly FakeProvider provider = new();

    [Fact]
    public async Task Sends_the_authorization_as_a_JSON_POST_with_reference_amount_and_currency()
    {
        provider.Respond(200, """{"status":"approved"}""");

        await Gateway().AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);

        var request = Assert.Single(provider.Requests);
        Assert.Equal("POST", request.Method);
        Assert.Equal("/v1/authorizations", request.Path);
        Assert.StartsWith("application/json", request.ContentType);
        using var json = JsonDocument.Parse(request.Body);
        Assert.Equal(3, json.RootElement.EnumerateObject().Count());
        Assert.Equal("ORD-7", json.RootElement.GetProperty("reference").GetString());
        Assert.Equal(12.5m, json.RootElement.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", json.RootElement.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_Approved()
    {
        provider.Respond(200, """{"status":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_Declined()
    {
        provider.Respond(200, """{"status":"declined"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Unknown_extra_fields_in_the_answer_are_ignored()
    {
        provider.Respond(200, """{"id":"a-1","status":"approved","risk":{"score":3}}""");
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_Declined_even_with_an_unparseable_body()
    {
        provider.Respond(402, "<html>payment required</html>");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_with_a_JSON_error_body_is_Declined()
    {
        provider.Respond(402, """{"error":"insufficient_funds"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failure_statuses_surface_as_errors_instead_of_a_decision(int status)
    {
        provider.Respond(status, """{"status":"approved"}""");
        await Assert.ThrowsAsync<HttpRequestException>(Authorize);
    }

    [Theory]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("""{}""")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_an_exact_approval_never_approves(string body)
    {
        provider.Respond(200, body);
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData("not json")]
    [InlineData("")]
    [InlineData("""{"status":{"value":"approved"}}""")]
    public async Task A_malformed_answer_fails_loudly_instead_of_approving(string body)
    {
        provider.Respond(200, body);
        await Assert.ThrowsAnyAsync<Exception>(Authorize);
    }

    private Task<AuthorizationOutcome> Authorize() =>
        Gateway().AuthorizeAsync("ORD-1", new Money(10m, "USD"), CancellationToken.None);

    private HttpPaymentGateway Gateway() => new(new HttpClient { BaseAddress = provider.BaseAddress });

    public void Dispose() => provider.Dispose();

    private sealed record Received(string Method, string Path, string? ContentType, string Body);

    private sealed class FakeProvider : IDisposable
    {
        private readonly HttpListener listener = new();
        private readonly List<Received> requests = [];
        private int status = 200;
        private string body = "";

        public FakeProvider()
        {
            // Retry on a different port if another process grabbed the chosen one.
            for (var attempt = 0; ; attempt++)
            {
                var port = Random.Shared.Next(20000, 60000);
                try
                {
                    listener.Prefixes.Clear();
                    listener.Prefixes.Add($"http://127.0.0.1:{port}/");
                    listener.Start();
                    BaseAddress = new Uri($"http://127.0.0.1:{port}");
                    break;
                }
                catch (HttpListenerException) when (attempt < 10) { }
            }
            _ = Task.Run(Loop);
        }

        public Uri BaseAddress { get; private set; } = null!;

        public IReadOnlyList<Received> Requests { get { lock (requests) return [.. requests]; } }

        public void Respond(int statusCode, string responseBody) { status = statusCode; body = responseBody; }

        private async Task Loop()
        {
            while (listener.IsListening)
            {
                HttpListenerContext context;
                try { context = await listener.GetContextAsync(); }
                catch { return; }

                using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
                var received = new Received(context.Request.HttpMethod, context.Request.Url!.AbsolutePath,
                    context.Request.ContentType, await reader.ReadToEndAsync());
                lock (requests) requests.Add(received);

                var bytes = Encoding.UTF8.GetBytes(body);
                context.Response.StatusCode = status;
                context.Response.ContentType = "application/json";
                await context.Response.OutputStream.WriteAsync(bytes);
                context.Response.Close();
            }
        }

        public void Dispose() => listener.Close();
    }
}
